12|struct { __uint(type, BPF_MAP_TYPE_HASH); __uint(max_entries, 64);
13| __type(key, __u64); __type(value, __u32); } scope SEC(".maps");
14|/* Exact (cgroup, filesystem UUID), additive; no wildcard/control exception. */
15|struct { __uint(type, BPF_MAP_TYPE_HASH); __uint(max_entries, 256);
16| __type(key, struct guard_binding); __type(value, __u32); } trusted SEC(".maps");
