21|static __always_inline int permitted(struct inode *inode, __u32 cmd, int ret, __u32 abi)
22|{
23| if (ret) return ret; /* Never override a preceding BPF LSM denial. */
24| __u32 zero = 0;
25| struct guard_config *cfg = bpf_map_lookup_elem(&settings, &zero);
26| if (!cfg || cfg->mode == GUARD_OFF) return 0;
27| __u64 cg = bpf_get_current_cgroup_id();
28| if (cfg->mode == GUARD_TEST && !bpf_map_lookup_elem(&scope, &cg)) return 0;
29| __u64 magic = BPF_CORE_READ(inode, i_sb, s_magic);
30| __u32 rdev = BPF_CORE_READ(inode, i_rdev);
31| __u16 mode = BPF_CORE_READ(inode, i_mode);
32| int control = (abi < 2 && (mode & 0170000) == 0020000 && rdev == cfg->control_rdev);
33| if (magic != 0x9123683e && !control) return 0; /* Numeric collisions elsewhere ignored. */
34| if (abi < 2 && ((cmd >> 8) & 255) != 0x94 && !generic_management(cmd)) return 0;
35| if (abi < 2 && !control && safe_ioctl(cmd)) return 0;
36| /* DEVICES_READY scans/registers devices in this kernel: control denies all. */
37| int matches = 0;
38| if (!control && (abi >= 2 || known_management(cmd))) {
39|   struct guard_binding binding = { .cgroup_id = cg };
40|   struct super_block *sb = BPF_CORE_READ(inode, i_sb);
41|   if (!bpf_core_read(binding.uuid, sizeof(binding.uuid), &sb->s_uuid)) {
42|     __u32 *allowed = bpf_map_lookup_elem(&trusted, &binding);
43|     matches = allowed && *allowed == 1;
44|   }
45| }
46| if (cfg->mode == GUARD_TEST && abi < 2 && !test_lifecycle(cmd)) matches = 0;
47| if (matches) {
48|   __u32 key = 2; __u64 *n = bpf_map_lookup_elem(&counters, &key);
49|   if (n) __sync_fetch_and_add(n, 1);
50|   return 0;
51| }
52| __u64 *n = bpf_map_lookup_elem(&counters, &abi);
53| if (n) __sync_fetch_and_add(n, 1);
54| return -1; /* EPERM */
55|}
56|SEC("lsm/file_ioctl")
57|int BPF_PROG(btrfs_ioctl, struct file *file, unsigned int cmd, unsigned long arg, int ret)
58|{ return permitted(BPF_CORE_READ(file, f_inode), cmd, ret, 0); }
59|SEC("lsm/file_ioctl_compat")
60|int BPF_PROG(btrfs_compat, struct file *file, unsigned int cmd, unsigned long arg, int ret)
61|{ return permitted(BPF_CORE_READ(file, f_inode), cmd, ret, 1); }
62|/* Empty subvolume rmdir is a deletion path independent of ioctl. */
63|SEC("lsm/inode_rmdir")
64|int BPF_PROG(btrfs_rmdir, struct inode *dir, struct dentry *dentry, int ret)
65|{
66| if (ret) return ret;
67| struct inode *inode = BPF_CORE_READ(dentry, d_inode);
68| if (!inode || BPF_CORE_READ(inode, i_ino) != 256) return 0;
69| return permitted(inode, 0, 0, 3);
