71|/* Moving/exchanging a subvolume root changes its storage object location. */
72|SEC("lsm/inode_rename")
73|int BPF_PROG(btrfs_rename, struct inode *old_dir, struct dentry *old_dentry,
74| struct inode *new_dir, struct dentry *new_dentry, int ret)
75|{
76| if (ret) return ret;
77| struct inode *old = BPF_CORE_READ(old_dentry, d_inode);
78| struct inode *new = BPF_CORE_READ(new_dentry, d_inode);
79| if (old && BPF_CORE_READ(old, i_ino) == 256) {
80|  int rc = permitted(old, 0, 0, 4); if (rc) return rc;
81| }
82| if (new && BPF_CORE_READ(new, i_ino) == 256) return permitted(new, 0, 0, 4);
83| return 0;
