{"content":"1|//! File descriptors are resolved once, validated and reused for every ioctl.
2|use anyhow::{Context, Result, ensure};
3|use std::ffi::CString;
4|use std::fs::File;
5|use std::os::fd::{AsFd, AsRawFd, FromRawFd};
6|use std::os::unix::fs::MetadataExt;
7|use std::path::{Component, Path};
8|use crate::policy::ObjectPin;
9|
10|#[repr(C)]
11|struct OpenHow { flags: u64, mode: u64, resolve: u64 }
12|const RESOLVE_NO_MAGICLINKS: u64 = 0x02;
13|const RESOLVE_NO_SYMLINKS: u64 = 0x04;
14|const RESOLVE_BENEATH: u64 = 0x08;
15|
16|pub fn checked_absolute(path: &str) -> Result<&Path> {
17|    let p = Path::new(path);
18|    ensure!(p.is_absolute() && !path.as_bytes().contains(&0), "absolute path required");
19|    ensure!(!path.split('/').any(|s| s == "." || s == ".."), "dot component forbidden");
20|    ensure!(p.components().all(|c| matches!(c, Component::RootDir | Component::Normal(_))), "invalid component");
21|    Ok(p)
22|}
23|
24|pub fn open_beneath(parent: &File, relative: &str, flags: i32, mode: u32) -> Result<File> {
25|    ensure!(!relative.starts_with('/') && !relative.split('/').any(|s| s == ".." || s == "."), "invalid relative path");
26|    let name = CString::new(relative)?;
27|    let how = OpenHow {
28|        flags: (flags | libc::O_CLOEXEC | libc::O_NOFOLLOW) as u64,
29|        mode: mode as u64,
30|        resolve: RESOLVE_BENEATH | RESOLVE_NO_SYMLINKS | RESOLVE_NO_MAGICLINKS,
31|    };
32|    // SAFETY: input buffers live for the syscall, size is exact Linux open_how.
33|    // No fallback: ENOSYS or unsupported flags fail closed.
34|    let raw = unsafe { libc::syscall(libc::SYS_openat2, parent.as_raw_fd(), name.as_ptr(),
35|        &how as *const OpenHow, std::mem::size_of::<OpenHow>()) };
36|    if raw < 0 { return Err(std::io::Error::last_os_error()).with_context(|| format!("openat2 {relative}")); }
37|    // SAFETY: successful syscall gives this function unique fd ownership.
38|    Ok(unsafe { File::from_raw_fd(raw as i32) })
39|}
40|
41|pub fn open_absolute(path: &str) -> Result<File> {
42|    checked_absolute(path)?;
43|    let root = File::open("/")?;
44|    if path == "/" { return Ok(root); }
45|    open_beneath(&root, path.trim_start_matches('/'), libc::O_RDONLY | libc::O_DIRECTORY, 0)
46|}
47|
48|pub fn trusted_metadata(file: &File, directory: bool) -> Result<()> {
49|    let m = file.metadata()?;
50|    ensure!(m.uid() == 0 && m.mode() & 0o022 == 0, "object must be root-owned and not group/world writable");
51|    ensure!(if directory { m.is_dir() } else { m.is_file() && m.nlink() == 1 }, "invalid object type/link count");
52|    Ok(())
53|}
54|
55|pub fn validate(file: &File, pin: &ObjectPin, secure: bool) -> Result<btrfs_uapi::subvolume::SubvolumeInfo> {
56|    if secure { trusted_metadata(file, true)?; }
57|    ensure!(file.metadata()?.ino() == pin.inode, "inode mismatch");
58|    let fs = btrfs_uapi::filesystem::filesystem_info(file.as_fd()).context("FS_INFO")?;
59|    ensure!(fs.uuid.to_string() == pin.filesystem_uuid, "filesystem UUID mismatch");
60|    let info = btrfs_uapi::subvolume::subvolume_info(file.as_fd()).context("GET_SUBVOL_INFO")?;
61|    ensure!(info.id == pin.subvolume_id && info.uuid.to_string() == pin.subvolume_uuid, "subvolume identity mismatch");
62|    Ok(info)
63|}
64|
65|pub fn pinned(pin: &ObjectPin, secure: bool) -> Result<File> {
66|    let file = open_absolute(&pin.path)?;
67|    validate(&file, pin, secure)?;
68|    Ok(file)
69|}
70|
71|/// Check every ancestor in a destination/state path against ordinary namespace
72|/// replacement. Root administrators are explicitly outside this threat boundary.
73|pub fn secure_ancestors(path: &str) -> Result<()> {
74|    checked_absolute(path)?;
75|    let mut prefix = String::new();
76|    let root = File::open("/")?;
77|    trusted_metadata(&root, true)?;
78|    for part in path.split('/').filter(|s| !s.is_empty()) {
79|        prefix.push('/'); prefix.push_str(part);
80|        trusted_metadata(&open_absolute(&prefix)?, true)?;
81|    }
82|    Ok(())
83|}
84|
85|pub fn list_names(dir: &File) -> Result<Vec<String>> {
86|    // The proc path is solely our own held fd, never caller-provided or used to
87|    // reopen an ioctl object. fd stays live during readdir.
88|    let mut names = std::fs::read_dir(format!("/proc/self/fd/{}", dir.as_raw_fd()))?
89|        .map(|e| Ok(e?.file_name().into_string().map_err(|_| anyhow::anyhow!("non-UTF8 managed entry"))?))
90|        .collect::<Result<Vec<_>>>()?;
91|    names.sort();
92|    Ok(names)
93|}
