2|use crate::engine::{Journal, State};
3|use crate::objects::{open_absolute, open_beneath, secure_ancestors, trusted_metadata};
4|use std::fs::File;
5|use std::io::{Read, Write};
6|use std::os::fd::AsRawFd;
7|
8|const STATE_DIRECTORY: &str = "/var/lib/opdbus-storage";
9|const MAX_STATE: u64 = 131072;
10|
11|pub fn load_policy() -> Result<crate::policy::Policy> {
12|    secure_ancestors("/etc/op-dbus")?;
13|    let dir = open_absolute("/etc/op-dbus")?;
14|    let mut file = open_beneath(&dir, "storage-policy.json", libc::O_RDONLY, 0)?;
15|    trusted_metadata(&file, false)?;
16|    ensure!(file.metadata()?.len() <= MAX_STATE, "oversized policy");
17|    let mut bytes = Vec::new(); file.read_to_end(&mut bytes)?;
18|    let policy: crate::policy::Policy = serde_json::from_slice(&bytes)?;
19|    policy.validate()?;
20|    Ok(policy)
21|}
22|
23|/// Held for service lifetime; prevents independent daemon instances from doing
24|/// reservations/count checks concurrently. Never creates or adopts state.
25|pub struct StateDirectory { directory: File, _lock: File }
26|impl StateDirectory {
27|    pub fn open() -> Result<Self> {
28|        secure_ancestors(STATE_DIRECTORY)?;
29|        let directory = open_absolute(STATE_DIRECTORY)?;
30|        let lock = open_beneath(&directory, "lock", libc::O_RDWR, 0)?;
31|        trusted_metadata(&lock, false)?;
32|        // SAFETY: lock remains live for this object's lifetime.
33|        ensure!(unsafe { libc::flock(lock.as_raw_fd(), libc::LOCK_EX | libc::LOCK_NB) } == 0,
34|            "storage lock unavailable: {}", std::io::Error::last_os_error());
35|        let mut result = Self { directory, _lock: lock };
36|        result.load().context("explicit root operator state bootstrap required")?;
37|        Ok(result)
38|    }
39|}
40|impl Journal for StateDirectory {
41|    fn load(&mut self) -> Result<State> {
42|        let mut file = open_beneath(&self.directory, "state.json", libc::O_RDONLY, 0)?;
43|        trusted_metadata(&file, false)?;
44|        ensure!(file.metadata()?.len() <= MAX_STATE, "oversized state");
45|        let mut bytes = Vec::new(); file.read_to_end(&mut bytes)?;
46|        Ok(serde_json::from_slice(&bytes)?)
47|    }
48|    fn save(&mut self, state: &State) -> Result<()> {
49|        let bytes = serde_json::to_vec(state)?;
50|        ensure!(bytes.len() as u64 <= MAX_STATE, "oversized state");
51|        let name = format!(".state-{}", uuid::Uuid::new_v4());
52|        let mut file = open_beneath(&self.directory, &name, libc::O_WRONLY | libc::O_CREAT | libc::O_EXCL, 0o600)?;
53|        file.write_all(&bytes)?;
54|        file.sync_all()?;
55|        let old = std::ffi::CString::new(name)?;
56|        let new = c"state.json";
57|        // SAFETY: both paths are single constant/generated names relative to
58|        // the same checked, held directory descriptor; buffers are live.
59|        ensure!(unsafe { libc::renameat(self.directory.as_raw_fd(), old.as_ptr(),
60|            self.directory.as_raw_fd(), new.as_ptr()) } == 0,
61|            "atomic state publication failed: {}", std::io::Error::last_os_error());
62|        self.directory.sync_all()?;
63|        Ok(())
64|    }
